<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>LatestGovtJobs Automation</title><style>
body{font-family:system-ui,-apple-system,Segoe UI,sans-serif;margin:0;background:#f4f6f8;color:#111827}nav{background:#111827;padding:14px 24px}nav a{color:#fff;text-decoration:none;margin-right:20px}.wrap{max-width:1180px;margin:28px auto;padding:0 18px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:20px;margin-bottom:18px;box-shadow:0 2px 8px rgba(0,0,0,.03)}h1{margin-top:0}table{width:100%;border-collapse:collapse}th,td{padding:11px;border-bottom:1px solid #eee;text-align:left;vertical-align:top}button,.btn{display:inline-block;background:#111827;color:white;border:0;border-radius:7px;padding:9px 13px;text-decoration:none;cursor:pointer}.crawl{background:#166534}.muted{color:#6b7280}.flash{background:#ecfdf5;border:1px solid #a7f3d0;padding:12px;border-radius:8px;margin-bottom:16px}.error{background:#fef2f2;border:1px solid #fecaca;padding:12px;border-radius:8px;margin-bottom:16px}.top-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.top-actions form{margin:0}
</style></head><body><nav><a href="/">Dashboard</a><a href="/sources">Sources</a><a href="/reviews">Review Queue</a></nav><main class="wrap"><?php if(session('status')): ?><div class="flash"><?= e(session('status')) ?></div><?php endif; ?><?php if(session('error')): ?><div class="error"><?= e(session('error')) ?></div><?php endif; ?><div class="card"><h1>Government Sources</h1><div class="top-actions"><form method="post" action="/sources/crawl-all"><?= csrf_field() ?><button class="crawl" type="submit">Crawl Now — All Active Sources</button></form><a class="btn" href="/sources/create">Add Government Source</a></div><p class="muted">The global crawl checks active sources one by one. Each source still uses its existing crawler mode and job-processing logic.</p></div><div class="card"><table><thead><tr><th>Source</th><th>Mode</th><th>Status</th><th>Last crawl</th><th>Action</th></tr></thead><tbody><?php foreach($sources as $s): ?><tr><td><strong><?= e($s->name) ?></strong><br><span class="muted"><?= e($s->organization) ?></span><br><small><?= e($s->recruitment_url) ?></small></td><td><?= e($s->crawler_mode->value) ?></td><td><?= e($s->status->value) ?></td><td><?= e($s->last_crawled_at ?: 'Never') ?></td><td><form style="display:inline" method="post" action="/sources/<?= (int)$s->id ?>/toggle"><?= csrf_field() ?><button type="submit"><?= $s->status->value==='active'?'Pause':'Activate' ?></button></form></td></tr><?php endforeach; ?></tbody></table><div style="margin-top:14px"><?= $sources->links() ?></div></div></main></body></html>